import { Component } from "@angular/core";

@Component({
  selector: "app-compteur",
  standalone: true,
  template: `
    <button (click)="incrementer()">{{ compteur }}</button>
  `
})
export class CompteurComponent {
  compteur = 0;

  incrementer() {
    this.compteur += 1;
  }
}
